interface S{type Item; fn get()->Item}
class I(let v:int) implements S{type Item=int; override fn get()->int=self.v}
fn first[T](x:T)->T.Item where T:S=x.get()
print(first(I(7)))

fn b(okay:bool)->result[int,text]{if okay{return ok(4)};return err("x")}
fn p(okay:bool)->result[int,text]{let x=b(okay)?;return ok(x+1)}
print(unwrap_ok(p(true)))
print(is_err(p(false)))

resource class H(let x:int){fn close()->unit{print("closed")}}
let h=H(3)
using owned=move h{print(owned.x)}

resource class H(let x:int){}
let h=H(1)
let y=move h
print(h.x)

@derive("Equal","Hash") class K(let x:int){}
let a=K(1)
let b=K(1)
print(a==b)
print(map_get(map_of(a,"ok"),b,"bad"))

use task
fn make()->fn[int,int]{var n=0; fn h(x:int)->int{n=n+x;return n};return h}
let a=task.actor(make())
print(await task.ask(a,2))
print(await task.ask(a,3))
task.stop(a)
